public inherited sharing class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String NAMED_CREDENTIAL_ENDPOINT = 'callout:FB_Exchange_Rates/v1/latest';

    @TestVisible
    private static Http httpProvider {
        get {
            if (httpProvider == null) {
                httpProvider = new Http();
            }
            return httpProvider;
        }
        set;
    }

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // --- Normalise and validate before any callout ---
        String normalisedBase = normalise(baseCurrency);
        if (!isValidCurrencyCode(normalisedBase)) {
            throw new ExchangeRateException('Invalid base currency code: ' + baseCurrency);
        }

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty.');
        }

        List<String> normalisedQuotes = new List<String>();
        Set<String> normalisedQuoteSet = new Set<String>();
        for (String quote : quoteCurrencies) {
            String normalisedQuote = normalise(quote);
            if (!isValidCurrencyCode(normalisedQuote)) {
                throw new ExchangeRateException('Invalid quote currency code: ' + quote);
            }
            if (normalisedQuoteSet.add(normalisedQuote)) {
                normalisedQuotes.add(normalisedQuote);
            }
        }

        // --- Build request ---
        String symbols = String.join(normalisedQuotes, ',');
        HttpRequest request = new HttpRequest();
        request.setEndpoint(NAMED_CREDENTIAL_ENDPOINT
            + '?base=' + EncodingUtil.urlEncode(normalisedBase, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8'));
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(30000);

        // --- Callout with one retry on 503 ---
        HttpResponse response = null;
        Integer attempts = 0;
        while (attempts < 2) {
            response = httpProvider.send(request);
            attempts++;
            if (response.getStatusCode() == 503) {
                // retry once with an identical request
                if (attempts < 2) {
                    continue;
                }
            }
            break;
        }

        Integer statusCode = response.getStatusCode();
        if (statusCode != 200) {
            throw new ExchangeRateException('Exchange rate API returned status code '
                + statusCode + ': ' + response.getBody());
        }

        // --- Parse body ---
        String body = response.getBody();
        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeStrict(body, Map<String, Object>.class);
        } catch (Exception e) {
            throw new ExchangeRateException('Could not parse response body: ' + e.getMessage());
        }

        if (parsed == null || parsed.get('rates') == null || !(parsed.get('rates') instanceof Map<String, Object>)) {
            throw new ExchangeRateException('Response body does not contain a valid rates object.');
        }

        Map<String, Object> rates = (Map<String, Object>) parsed.get('rates');

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : normalisedQuoteSet) {
            Object rateValue = rates.get(quote);
            if (rateValue == null) {
                throw new ExchangeRateException('No rate found for requested currency: ' + quote);
            }
            Decimal rate;
            try {
                rate = Decimal.valueOf(String.valueOf(rateValue));
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid rate value for currency '
                    + quote + ': ' + String.valueOf(rateValue));
            }
            result.put(quote, rate);
        }
        return result;
    }

    private static String normalise(String currencyCode) {
        if (currencyCode == null) {
            return null;
        }
        return currencyCode.trim().toUpperCase();
    }

    private static Boolean isValidCurrencyCode(String currencyCode) {
        return currencyCode != null && currencyCode.matches('^[A-Z]{3}$');
    }
}
