public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (body == null || body.trim().isEmpty()) {
            throw new PayloadException('Order payload body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Order payload is not valid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Order payload is not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        String orderNumber = getString(root, 'number');
        if (orderNumber == null || orderNumber.trim().isEmpty()) {
            throw new PayloadException('Order payload is missing a blank-free "number"');
        }

        Order order = new Order();
        order.orderNumber = orderNumber;

        // date (optional)
        String dateStr = getString(root, 'date');
        if (dateStr != null && !dateStr.trim().isEmpty()) {
            List<String> parts = dateStr.split('-', 3);
            if (parts.size() == 3) {
                try {
                    Integer y = Integer.valueOf(parts[0]);
                    Integer m = Integer.valueOf(parts[1]);
                    Integer d = Integer.valueOf(parts[2]);
                    order.orderDate = Date.newInstance(y, m, d);
                } catch (Exception e) {
                    throw new PayloadException('Invalid "date" in order payload: ' + dateStr);
                }
            } else {
                throw new PayloadException('Invalid "date" in order payload: ' + dateStr);
            }
        }

        order.currencyCode = getString(root, 'currency');

        // customer (optional)
        Object customerObj = root.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            order.customerEmail = getString((Map<String, Object>) customerObj, 'email');
        }

        // lines (optional)
        order.lines = new List<Line>();
        Object linesObj = root.get('lines');
        if (linesObj instanceof List<Object>) {
            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Order line is not a JSON object');
                }
                order.lines.add(parseLine((Map<String, Object>) lineObj));
            }
        } else if (linesObj != null) {
            throw new PayloadException('"lines" is not a JSON array');
        }

        // total
        Decimal total = 0;
        for (Line l : order.lines) {
            total += l.lineTotal;
        }
        order.total = total.setScale(2, System.RoundingMode.HALF_UP);

        return order;
    }

    private static Line parseLine(Map<String, Object> lineMap) {
        Line line = new Line();

        String sku = getString(lineMap, 'sku');
        if (sku == null || sku.trim().isEmpty()) {
            throw new PayloadException('Order line is missing "sku"');
        }
        line.sku = sku;

        Object qtyObj = lineMap.get('quantity');
        if (qtyObj == null) {
            throw new PayloadException('Order line "' + sku + '" is missing "quantity"');
        }
        Decimal qtyDec;
        try {
            qtyDec = toDecimal(qtyObj);
        } catch (Exception e) {
            throw new PayloadException('Order line "' + sku + '" has a non-numeric "quantity"');
        }
        if (qtyDec == null || qtyDec <= 0) {
            throw new PayloadException('Order line "' + sku + '" has a non-positive "quantity"');
        }
        line.quantity = (Integer) qtyDec;

        Object priceObj = lineMap.get('unitPrice');
        if (priceObj == null) {
            throw new PayloadException('Order line "' + sku + '" is missing "unitPrice"');
        }
        Decimal unitPrice;
        try {
            unitPrice = toDecimal(priceObj);
        } catch (Exception e) {
            throw new PayloadException('Order line "' + sku + '" has a non-numeric "unitPrice"');
        }
        if (unitPrice == null || unitPrice < 0) {
            throw new PayloadException('Order line "' + sku + '" has a negative "unitPrice"');
        }
        line.unitPrice = unitPrice;

        Object discountObj = lineMap.get('discount');
        Decimal discount = 0;
        if (discountObj != null) {
            try {
                discount = toDecimal(discountObj);
            } catch (Exception e) {
                throw new PayloadException('Order line "' + sku + '" has a non-numeric "discount"');
            }
            if (discount == null) {
                discount = 0;
            }
        }
        line.discount = discount;

        line.lineTotal = (line.quantity * line.unitPrice * (1 - line.discount))
            .setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    private static String getString(Map<String, Object> map, String key) {
        Object val = map.get(key);
        return (val instanceof String) ? (String) val : null;
    }

    private static Decimal toDecimal(Object val) {
        if (val instanceof Decimal || val instanceof Integer || val instanceof Long || val instanceof Double) {
            return Decimal.valueOf(String.valueOf(val));
        }
        throw new PayloadException('Expected a JSON number');
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines == null ? 0 : order.lines.size());
        ack.put('total', order.total == null ? 0 : order.total);
        return JSON.serialize(ack);
    }
}
