public with sharing class OpportunityPipelineHandler {

    /**
     * Recalculates FB_Open_Pipeline__c and FB_Open_Opportunities__c on every
     * Account affected by the current Opportunity DML statement.
     *
     * The calculation is always performed from a fresh aggregate query on
     * Opportunity, so the totals are correct no matter how many DML statements
     * touch the same records within one transaction (Flow, Apex, tests, etc.).
     *
     * Recursion safety: we only issue an Account update when a total actually
     * changed. The legacy AccountTrigger copies Rating onto open opportunities
     * on every Account update; that re-fires this handler, but the recomputed
     * totals are then unchanged, so no further DML happens and the loop stops.
     */
    public static void run(List<Opportunity> newList, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();

        if (newList != null) {
            for (Opportunity o : newList) {
                accountIds.add(o.AccountId);
            }
        }
        if (oldMap != null) {
            // On update this captures the previous AccountId (opportunity moved
            // accounts); on delete newList is null and oldMap holds all owners.
            for (Opportunity o : oldMap.values()) {
                accountIds.add(o.AccountId);
            }
        }
        accountIds.remove(null);

        if (accountIds.isEmpty()) {
            return;
        }

        // Current open-opportunity totals per account.
        Map<Id, Decimal> sums = new Map<Id, Decimal>();
        Map<Id, Integer> counts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) oppCount
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            sums.put(accId, (Decimal) ar.get('totalAmount'));
            counts.put(accId, (Integer) ar.get('oppCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]) {
            // Accounts with no open opportunities (last one closed/deleted/moved)
            // get 0 and 0, never blank. NULL amounts count as 0.
            Decimal newSum = sums.containsKey(acc.Id) ? sums.get(acc.Id) : 0;
            Integer newCount = counts.containsKey(acc.Id) ? counts.get(acc.Id) : 0;

            Decimal currentSum = acc.FB_Open_Pipeline__c == null ? 0 : acc.FB_Open_Pipeline__c;
            Integer currentCount = acc.FB_Open_Opportunities__c == null ? 0 : acc.FB_Open_Opportunities__c.intValue();

            if (currentSum != newSum || currentCount != newCount) {
                acc.FB_Open_Pipeline__c = newSum;
                acc.FB_Open_Opportunities__c = newCount;
                accountsToUpdate.add(acc);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
