/**
 * Service that computes closed-won opportunity revenue per account
 * for the current calendar year.
 */
public inherited sharing class OpportunityRollupService {

    /**
     * Returns the sum of Amount over won opportunities with a CloseDate in the
     * current calendar year, keyed by Account Id.
     *
     * - Every requested account Id appears as a key (0 when there is no
     *   qualifying revenue, never null).
     * - Ids that were not requested are never keys.
     * - A null or empty input yields an empty map.
     * - Sums are computed in the database via a single aggregate query.
     * - Runs with inherited sharing, so results respect the running user's access.
     */
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        Map<Id, Decimal> result = new Map<Id, Decimal>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Initialize every requested account to 0 so all requested Ids are keys.
        for (Id accountId : accountIds) {
            result.put(accountId, 0);
        }

        // Single aggregate query: sums computed in the database.
        // CloseDate = THIS_YEAR covers the current calendar year (Jan 1 – Dec 31).
        // inherited sharing on the class enforces the running user's record access.
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = true
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) ar.get('AccountId');
            // SUM ignores blank Amounts; coalesce defensively in case of null.
            Decimal total = ar.get('totalAmount') == null
                ? 0
                : (Decimal) ar.get('totalAmount');
            result.put(accountId, total);
        }

        return result;
    }
}
