        // Unit of work mock: registerDirty/commitWork become recorded no-ops.
        m.uow = (fflib_ISObjectUnitOfWork) m.mocks.mock(fflib_SObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(m.uow);

