public inherited with sharing class Opportunities extends fflib_SObjectDomain {

    public static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjects) {
            return new Opportunities(sObjects);
        }
    }

    public void onAfterInsert() {
        startFulfilmentForQualifyingRecords();
    }

    public void onAfterUpdate(Map<Id, SObject> existingRecords) {
        Map<Id, Opportunity> oldRecords = (Map<Id, Opportunity>) existingRecords;
        List<Opportunity> qualifying = new List<Opportunity>();

        for (Opportunity record : (List<Opportunity>) getRecords()) {
            Opportunity oldRecord = oldRecords.get(record.Id);
            if (oldRecord != null
                && record.StageName == STAGE_CLOSED_WON
                && oldRecord.StageName != STAGE_CLOSED_WON) {
                qualifying.add(record);
            }
        }

        if (!qualifying.isEmpty()) {
            startFulfilment(qualifying);
        }
    }

    private void startFulfilmentForQualifyingRecords() {
        List<Opportunity> qualifying = new List<Opportunity>();
        for (Opportunity record : (List<Opportunity>) getRecords()) {
            if (record.StageName == STAGE_CLOSED_WON) {
                qualifying.add(record);
            }
        }

        if (!qualifying.isEmpty()) {
            startFulfilment(qualifying);
        }
    }

    private void startFulfilment(List<Opportunity> qualifyingRecords) {
        Set<Id> opportunityIds = new Set<Id>();
        for (Opportunity record : qualifyingRecords) {
            opportunityIds.add(record.Id);
        }

        // Per trigger invocation this path runs once for the batched records,
        // so startFulfilment is called at most once with all qualifying ids.
        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class
            );
        service.startFulfilment(opportunityIds);
    }
}
