public with sharing class CaseSurveyJob implements Queueable {
    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext ctx) {
        Case c = [
            SELECT Id, CaseNumber, ContactId
            FROM Case
            WHERE Id = :caseId
        ];

        // Re-check the contact: data may have changed between enqueue and execute.
        if (c.ContactId == null) {
            return;
        }

        insert new Task(
            WhatId      = c.Id,
            WhoId       = c.ContactId,
            Subject     = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status      = 'Not Started'
        );
    }
