import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    errorMessage;

    debounceTimer;
    requestCounter = 0;

    renderedCallback() {
        // no-op; kept minimal
    }

    connectedCallback() {
        this.requestCounter = 0;
    }

    disconnectedCallback() {
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = undefined;
        }
        // Invalidate any in-flight request so its response is ignored.
        this.requestCounter++;
    }

    handleSearchChange(event) {
        this.searchTerm = event.target.value;
        this.errorMessage = undefined;

        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = undefined;
        }

        const trimmed = (this.searchTerm || '').trim();
        if (trimmed.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            return;
        }

        this.debounceTimer = setTimeout(() => {
            this.debounceTimer = undefined;
            this.performSearch(trimmed);
        }, DEBOUNCE_DELAY_MS);
    }

    async performSearch(trimmedSearchTerm) {
        const currentRequest = ++this.requestCounter;
        try {
            const results = await searchContacts({ searchTerm: trimmedSearchTerm });
            if (currentRequest !== this.requestCounter) {
                // A newer request exists (or the component was removed); ignore stale response.
                return;
            }
            this.contacts = results || [];
            this.errorMessage = undefined;
        } catch (error) {
            if (currentRequest !== this.requestCounter) {
                return;
            }
            this.contacts = [];
            this.errorMessage = error.body ? error.body.message : error.message;
        }
    }

    get hasResults() {
        return this.contacts.length > 0;
    }
}
