import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    /** Array of { key, productName, quantity } */
    @api lines;

    hasError = false;

    handleAction(event) {
        const action = event.currentTarget.dataset.action;

        if (action === 'reset') {
            this.resetLines();
        } else if (action === 'submit') {
            this.submitLines();
        }
    }

    resetLines() {
        this.template.querySelectorAll('c-line-item-editor').forEach((editor) => {
            editor.reset();
        });
        this.hasError = false;
    }

    submitLines() {
        const editors = this.template.querySelectorAll('c-line-item-editor');

        // Validate every editor so all invalid lines show their errors at once.
        const allValid = Array.from(editors).reduce(
            (valid, editor) => editor.validate() && valid,
            true
        );

        if (allValid) {
            const lines = Array.from(editors).map((editor) => editor.getValue());
            this.hasError = false;
            this.dispatchEvent(
                new CustomEvent('submit', { detail: { lines } })
            );
        } else {
            this.hasError = true;
        }
    }
}
