export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        this[event.target.dataset.field] = event.detail.value;
    }

    handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');
        const domain = this.email.includes('@')
            ? this.email.split('@').pop().trim().toLowerCase()
            : '';

        if (PERSONAL_EMAIL_DOMAINS.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        let allValid = true;
        this.template.querySelectorAll('lightning-input').forEach((input) => {
            if (!input.reportValidity()) {
                allValid = false;
            }
        });

        if (!allValid) {
            return;
        }

        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error.body.message
                    })
                );
            });
    }
}
