import { LightningElement, api } from 'lwc';

const NAV_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;
    @api options = [];

    _value;
    activeValue;

    @api
    get value() {
        return this._value;
    }
    set value(newValue) {
        this._value = newValue;
        this.syncActiveToValue();
    }

    @api
    set options(newOptions) {
        this._options = newOptions || [];
        this.syncActiveToValue();
    }
    get options() {
        return this._options;
    }

    constructor() {
        super();
        this._options = [];
        this.syncActiveToValue();
    }

    get selectedIndex() {
        if (this._value === undefined || this._value === null || this._value === '') {
            return -1;
        }
        return this._options.findIndex((o) => o.value === this._value);
    }

    get activeIndex() {
        const idx = this._options.findIndex((o) => o.value === this.activeValue);
        if (idx !== -1) {
            return idx;
        }
        return this.selectedIndex !== -1 ? this.selectedIndex : this._options.length ? 0 : -1;
    }

    get activeId() {
        const idx = this.activeIndex;
        return idx === -1 ? null : this.optionId(idx);
    }

    get items() {
        const activeIdx = this.activeIndex;
        return this._options.map((option, index) => ({
            ...option,
            id: this.optionId(index),
            isSelected: option.value === this._value,
            ariaSelected: option.value === this._value ? 'true' : 'false',
            isActive: index === activeIdx,
        }));
    }

    optionId(index) {
        return `${this.template.host ? '' : ''}option-${index}`;
    }

    syncActiveToValue() {
        this.activeValue = this.selectedIndex !== -1 ? this._value : this._options.length
            ? this._options[0].value
            : undefined;
    }

    moveActive(delta) {
        const max = this._options.length - 1;
        if (max < 0) {
            return;
        }
        const idx = this.activeIndex;
        this.activeValue = this._options[Math.max(0, Math.min(max, idx + delta))].value;
    }

    moveTo(index) {
        if (this._options.length) {
            this.activeValue = this._options[index].value;
        }
    }

    handleKeydown(event) {
        if (!NAV_KEYS.includes(event.key)) {
            return;
        }
        event.preventDefault();
        switch (event.key) {
            case 'ArrowDown':
                this.moveActive(1);
                break;
            case 'ArrowUp':
                this.moveActive(-1);
                break;
            case 'Home':
                this.moveTo(0);
                break;
            case 'End':
                this.moveTo(this._options.length - 1);
                break;
            case 'Enter':
            case ' ':
                this.selectByIndex(this.activeIndex);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const li = event.currentTarget;
        const value = li.dataset.value;
        const idx = this._options.findIndex((o) => o.value === value);
        if (idx !== -1) {
            this.activeValue = value;
            this.selectByIndex(idx);
        }
    }

    selectByIndex(index) {
        if (index < 0 || index >= this._options.length) {
            return;
        }
        const option = this._options[index];
        this.activeValue = option.value;
        if (option.value !== this._value) {
            this._value = option.value;
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value: option.value },
                })
            );
        }
    }
}
