import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading = '';
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    set tasks(value) {
        // Work on our own deep copy; never mutate the parent's data.
        this._tasks = value ? value : [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    get tasks() {
        return this._tasks;
    }

    // Display-only: upper-case in the template, parent's value untouched.
    get displayHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        // Reassign (not push) so the template re-renders.
        this.items = [...this.items, { id: `new-${this.nextId++}`, label, done: false }];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        // Reassign task objects so change detection picks it up.
        this.items = this.items.map((task) =>
            task.id === id ? { ...task, done: !task.done } : task
        );
    }
}
