public with sharing class EmployerService {

    /**
     * Sets the current employer (primary NPSP affiliation) for a set of contacts.
     *
     * Leverages NPSP's standard affiliation mechanism: when an Affiliation is
     * created/updated with npe5__Primary__c = true and npe5__Status__c = 'Current',
     * the NPSP trigger:
     *   - demotes the previous primary affiliation to Former, non-primary,
     *     stamping npe5__EndDate__c with today,
     *   - maintains Contact.npsp__Primary_Affiliation__c,
     *   - leaves household assignments untouched.
     *
     * Limits: 1 SOQL query, at most 2 DML statements.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Single query: fetch each contact's primary affiliation and any existing
        // affiliation with the target organization (any status).
        List<npe5__Affiliation__c> existing = [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c,
                   npe5__Primary__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
              AND (npe5__Primary__c = true
                   OR npe5__Organization__c IN :employerByContactId.values())
        ];

        Map<Id, npe5__Affiliation__c> primaryByContact = new Map<Id, npe5__Affiliation__c>();
        Map<Id, npe5__Affiliation__c> toOrgByContact = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : existing) {
            if (aff.npe5__Primary__c && aff.npe5__Status__c == 'Current') {
                primaryByContact.put(aff.npe5__Contact__c, aff);
            }
            if (aff.npe5__Organization__c == employerByContactId.get(aff.npe5__Contact__c)) {
                toOrgByContact.put(aff.npe5__Contact__c, aff);
            }
        }

        List<npe5__Affiliation__c> toInsert = new List<npe5__Affiliation__c>();
        List<npe5__Affiliation__c> toUpdate = new List<npe5__Affiliation__c>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }

            npe5__Affiliation__c currentPrimary = primaryByContact.get(contactId);
            // Already the current primary employer -> nothing to do.
            if (currentPrimary != null && currentPrimary.npe5__Organization__c == orgId) {
                continue;
            }

            npe5__Affiliation__c existingToOrg = toOrgByContact.get(contactId);
            if (existingToOrg != null && existingToOrg.npe5__Status__c == 'Current') {
                // Reactivate/promote the existing Current affiliation to primary.
                existingToOrg.npe5__Primary__c = true;
                existingToOrg.npe5__Status__c = 'Current';
                toUpdate.add(existingToOrg);
            } else if (existingToOrg != null) {
                // Existing Former affiliation with this org: revive it as Current primary.
                existingToOrg.npe5__Primary__c = true;
                existingToOrg.npe5__Status__c = 'Current';
                existingToOrg.npe5__StartDate__c = Date.today();
                existingToOrg.npe5__EndDate__c = null;
                toUpdate.add(existingToOrg);
            } else {
                // Brand new primary employer affiliation. NPSP demotes the old
                // primary (Former, non-primary, EndDate = today), maintains
                // Contact.npsp__Primary_Affiliation__c, and preserves households.
                toInsert.add(new npe5__Affiliation__c(
                    npe5__Contact__c = contactId,
                    npe5__Organization__c = orgId,
                    npe5__Status__c = 'Current',
                    npe5__Primary__c = true,
                    npe5__StartDate__c = Date.today()
                ));
            }
        }

        // At most two DML statements.
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
