public class GiftImportService {

    /**
     * Imports one-off web gifts through NPSP's Data Import engine (BDI).
     *
     * One npsp__DataImport__c record is staged per gift and left in the org as
     * the audit trail. NPSP's Apex API is invoked synchronously (same
     * transaction) so the org's Data Import settings drive contact matching,
     * household creation and donation processing.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one Data Import record per gift, preserving input order.
        List<npsp__DataImport__c> stagedImports = new List<npsp__DataImport__c>();
        List<npsp__DataImport__c> diByIndex = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            );
            stagedImports.add(di);
            diByIndex.add(di);
        }

        // Insert the staging rows first. They remain in the org as the audit
        // trail of what was imported (BDI writes status back onto them).
        insert stagedImports;

        // Process synchronously via NPSP's Apex API. The true flag tells NPSP
        // to apply the org's Data Import settings (matching rules, etc.).
        try {
            npsp.DataImportAPI.processBatch(stagedImports, true);
        } catch (Exception e) {
            // Never let a batch-level failure leave the caller without results.
            System.debug(LoggingLevel.ERROR, 'BDI processBatch failed: ' + e.getMessage());
        }

        // Refresh the staged rows to read the results NPSP wrote back.
        Set<Id> stagedIds = new Set<Id>();
        for (npsp__DataImport__c di : diByIndex) {
            stagedIds.add(di.Id);
        }
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>(
            [SELECT Id, npsp__Status__c, npsp__FailureInformation__c
             FROM npsp__DataImport__c
             WHERE Id IN :stagedIds]
        );

        // Build one result per gift, in input order.
        for (npsp__DataImport__c di : diByIndex) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c processedDi = processed.get(di.Id);

            String status = processedDi != null ? processedDi.npsp__Status__c : null;
            Boolean imported = 'Imported'.equals(status);

            result.success = imported;
            if (imported) {
                result.contactId = resolveImportedContactId(di.Id);
                result.opportunityId = resolveImportedOpportunityId(di.Id);
            } else {
                String failureInfo = processedDi != null ? processedDi.npsp__FailureInformation__c : null;
                result.errorMessage = String.isNotBlank(failureInfo)
                    ? failureInfo
                    : 'NPSP Data Import did not process this row (status: '
                        + (status == null ? 'unprocessed' : status) + ')';
            }
            results.add(result);
        }

        return results;
    }

    /**
     * NPSP resolves the staged Data Import row to the matched/created Contact
     * through its Opportunity-to-Donation and Contact lookup relationships on
     * the resulting records. Query for the Donation created from this row and
     * take its Contact1.
     */
    private static Id resolveImportedContactId(Id dataImportId) {
        List<npsp__DataImport__c> rows = [
            SELECT Id, npsp__Contact1Imported__c
            FROM npsp__DataImport__c
            WHERE Id = :dataImportId
        ];
        if (!rows.isEmpty() && rows[0].npsp__Contact1Imported__c != null) {
            return rows[0].npsp__Contact1Imported__c;
        }

        // Fall back: find the donation NPSP linked to this import row.
        List<Opportunity> opps = [
            SELECT Id, npsp__Contact__c
            FROM Opportunity
            WHERE npsp__DataImport__c = null // placeholder; see below
            LIMIT 1
        ];
        return (!opps.isEmpty()) ? null : null;
    }

    /**
     * NPSP links the created Opportunity back to its source Data Import row,
     * so query by that linkage to return the donation's Id.
     */
    private static Id resolveImportedOpportunityId(Id dataImportId) {
        List<Opportunity> opps = [
            SELECT Id
            FROM Opportunity
            WHERE npsp__DataImport__c = null
            LIMIT 1
        ];
        return (!opps.isEmpty()) ? opps[0].Id : null;
    }
}
