        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one Data Import record per gift, preserving input order.
        List<npsp__DataImport__c> stagedImports = new List<npsp__DataImport__c>();
        for (WebGift gift : gifts) {
            stagedImports.add(new npsp__DataImport__c(
                npsp__Contact1_Firstname__c = gift.firstName,
                npsp__Contact1_Lastname__c = gift.lastName,
                npsp__Contact1_Personal_Email__c = gift.email,
                npsp__Donation_Amount__c = gift.amount,
                npsp__Donation_Date__c = gift.giftDate,
                npsp__Donation_Donor__c = 'Contact1'
            ));
        }

        // Insert the staging rows. They remain in the org as the audit trail;
        // BDI writes Status / imported-Id / FailureInformation back onto them.
        insert stagedImports;

        // Process synchronously via NPSP's Apex API. The second argument tells
        // NPSP to apply the org's Data Import settings (default matching on
        // first name + last name + email; no donation matching).
        try {
            npsp.DataImportAPI.processBatch(stagedImports, true);
        } catch (Exception e) {
            // A batch-level exception must not stop the whole call; results are
            // derived from each row's status below, so failed rows simply
            // report failure while successfully imported rows still count.
            System.debug(LoggingLevel.ERROR,
                'GiftImportService: BDI processBatch exception: ' + e.getMessage());
        }

        // Re-query the staged rows for the results NPSP wrote back to them.
        Set<Id> stagedIds = new Set<Id>();
        for (npsp__DataImport__c di : stagedImports) {
            stagedIds.add(di.Id);
        }
        Map<Id, npsp__DataImport__c> processed = new Map<Id, npsp__DataImport__c>([
            SELECT Id,
                   npsp__Status__c,
                   npsp__FailureInformation__c,
                   npsp__Contact1Imported__c,
                   npsp__DonationImported__c
            FROM npsp__DataImport__c
            WHERE Id IN :stagedIds
        ]);

        // One result per gift, in input order.
        for (npsp__DataImport__c di : stagedImports) {
            ImportResult result = new ImportResult();
            npsp__DataImport__c row = processed.get(di.Id);
            String status = (row == null) ? null : row.npsp__Status__c;

            if ('Imported'.equals(status)) {
                result.success = true;
                result.contactId = (row != null) ? row.npsp__Contact1Imported__c : null;
                result.opportunityId = (row != null) ? row.npsp__DonationImported__c : null;
            } else {
                result.success = false;
                String failureInfo = (row == null) ? null : row.npsp__FailureInformation__c;
                result.errorMessage = String.isNotBlank(failureInfo)
                    ? failureInfo
                    : 'NPSP Data Import did not import this row (status: '
                        + (status == null ? 'unprocessed' : status) + ')';
            }
            results.add(result);
        }

        return results;
    }
