public with sharing class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static final String PSC_OBJECT = 'npsp__Partial_Soft_Credit__c';

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---- Validation phase: no DML until the whole call is validated ----

        Set<Id> oppIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req == null || req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Request must specify opportunityId and contactId.');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive number.');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Soft credit role must not be blank.');
            }
            oppIds.add(req.opportunityId);
        }

        // Query 1: opportunities
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c FROM Opportunity WHERE Id IN :oppIds]
        );

        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppsById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId +
                    ' is the primary contact on opportunity ' + req.opportunityId +
                    ' and cannot receive a partial soft credit.'
                );
            }
            if (opp.Amount == null || req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount ' + req.amount +
                    ' exceeds the opportunity amount on ' + req.opportunityId
                );
            }
        }

        // Query 2: existing contact roles for these opportunity/contact pairs
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            contactIds.add(req.contactId);
        }
        Map<String, OpportunityContactRole> ocrByKey = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ]) {
            ocrByKey.put(ocr.OpportunityId + '-' + ocr.ContactId, ocr);
        }

        // Query 3: existing partial soft credits for these pairs
        Map<String, npsp__Partial_Soft_Credit__c> pscByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ]) {
            pscByKey.put(psc.npsp__Opportunity__c + '-' + psc.npsp__Contact__c, psc);
        }

        // ---- Build DML payloads ----
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            OpportunityContactRole ocr = ocrByKey.get(key);

            if (ocr == null) {
                ocr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(ocr);
            } else if (ocr.Role != req.role) {
                OpportunityContactRole upd = new OpportunityContactRole(
                    Id = ocr.Id,
                    Role = req.role
                );
                ocrsToUpdate.add(upd);
            }
            // Keep the (possibly updated) OCR available for the PSC linkage below.
            ocrByKey.put(key, ocr);
        }

        // Insert/update contact roles first so new OCRs have Ids for PSC linkage.
        // DML 1 + 2 (only the needed one of these two actually issues statements,
        // but we stay well within the 4-statement budget either way).
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }
        if (!ocrsToUpdate.isEmpty()) {
            update ocrsToUpdate;
        }

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            OpportunityContactRole ocr = ocrByKey.get(key);

            npsp__Partial_Soft_Credit__c psc = pscByKey.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Contact_Name__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocr != null ? String.valueOf(ocr.Id) : null
                );
                pscsToInsert.add(psc);
            } else {
                psc.npsp__Amount__c = req.amount;
                psc.npsp__Role_Name__c = req.role;
                psc.npsp__Contact_Role_ID__c = ocr != null ? String.valueOf(ocr.Id) : null;
                pscsToUpdate.add(psc);
            }
        }

        // DML 3 + 4
        if (!pscsToInsert.isEmpty()) {
            insert pscsToInsert;
        }
        if (!pscsToUpdate.isEmpty()) {
            update pscsToUpdate;
        }
    }
}
