```apex
public with sharing class RecordAccessService {

    // UserRecordAccess supports filtering on at most 200 RecordIds per query.
    // Chunking at 200 keeps a 2,000-ID request within the 20-query limit.
    private static final Integer CHUNK_SIZE = 200;

    /**
     * @description Returns the subset of recordIds that the running user can edit,
     *              as reported by UserRecordAccess.HasEditAccess. Honors object
     *              permissions, ownership, sharing, role hierarchy, and
     *              View All / Modify All data.
     * @param recordIds Candidate record Ids, possibly spanning multiple objects; may be null.
     * @return Editable record Ids; empty set (never null) for null/empty input.
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();
        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // De-duplicate while preserving chunking.
        Set<Id> uniqueIds = new Set<Id>(recordIds);
        List<Id> idList = new List<Id>(uniqueIds);

        for (Integer start = 0; start < idList.size(); start += CHUNK_SIZE) {
            Integer end = Math.min(start + CHUNK_SIZE, idList.size());
            List<Id> chunk = idList.subList(start, end);

            for (UserRecordAccess acc : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND HasEditAccess = true
                  AND RecordId IN :chunk
            ]) {
                result.add(acc.RecordId);
            }
        }

        return result;
    }
}
