public with sharing class EmployeeDirectoryService {

    /**
     * Returns the FB_Employee__c records the running user can see via sharing,
     * ordered by Name, with any custom fields the user cannot read (per FLS)
     * removed from the returned records entirely.
     */
    public static List<FB_Employee__c> getDirectory() {
        // Query enforces row-level sharing (with sharing) and object-level
        // permissions: a user without object read access simply gets no rows.
        List<FB_Employee__c> records = [
            SELECT Id, Name, Department__c, Salary__c, Personal_Email__c
            FROM FB_Employee__c
            ORDER BY Name ASC
        ];

        if (records.isEmpty()) {
            return records;
        }

        // Enforce field-level security: stripInaccessible removes any fields
        // the running user cannot read from the returned sObjects, so they are
        // absent rather than null. Never throws for partially readable field sets.
        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            records
        );

        return decision.getRecords();
    }
}
