```apex
/**
 * @description Creates an onboarding Task for the account owner when a new
 *              Account is created with Type 'Customer - Direct' or
 *              'Customer - Channel'. Registered on the Account after-insert
 *              context via Trigger_Action__mdt (Order 10).
 *
 *              Bulk-safe: accumulates all tasks and performs a single DML
 *              statement per trigger execution; no DML when no account
 *              qualifies.
 */
public inherited sharing class TA_Account_CreateOnboardingTask
        implements TriggerAction.AfterInsert {

    private static final Set<String> QUALIFYING_TYPES = new Set<String>{
        'Customer - Direct',
        'Customer - Channel'
    };

    private static final String TASK_SUBJECT = 'Onboard new customer';
    private static final Integer DUE_IN_DAYS = 7;

    /**
     * @description Inserts one onboarding Task per qualifying new Account,
     *              owned by the Account's owner.
     * @param triggerNew the newly created Accounts
     */
    public void afterInsert(List<SObject> triggerNew) {
        List<Task> onboardingTasks = new List<Task>();

        for (SObject record : triggerNew) {
            Account account = (Account) record;
            if (account.Type != null
                    && QUALIFYING_TYPES.contains(account.Type)
                    && account.OwnerId != null) {
                onboardingTasks.add(new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = account.Id,
                    OwnerId = account.OwnerId,
                    ActivityDate = Date.today().addDays(DUE_IN_DAYS),
                    Status = 'Not Started',
                    Priority = 'Normal'
                ));
            }
        }

        if (!onboardingTasks.isEmpty()) {
            insert onboardingTasks;
        }
    }
}
