public inherited sharing class ContactImportService {

    private static final String WELCOME_TASK_ACTION = 'TA_Contact_CreateWelcomeTask';

    /**
     * Inserts the given contacts with the TA_Contact_CreateWelcomeTask trigger action
     * skipped via the Trigger Actions Framework bypass API. All other Contact
     * automation (including TA_Contact_FormatPhone) still runs.
     *
     * The bypass is always cleared afterwards, even if the DML fails, so that
     * contacts inserted later in the same transaction behave normally.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        Boolean bypassWasAlreadyActive = MetadataTriggerHandler.isBypassed(WELCOME_TASK_ACTION);
        if (!bypassWasAlreadyActive) {
            MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION);
        }

        try {
            insert contacts;
        } finally {
            // Restore the previous state so later inserts in this transaction
            // get their welcome tasks as usual.
            if (!bypassWasAlreadyActive) {
                MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION);
            }
        }
    }
}
