/**
 * Trigger Action: prevents two contacts on the same account from sharing an
 * email address (case-insensitive). Runs in before insert and before update
 * so failing records get a record-level error while valid records in the
 * same save still commit (partial save support via addError).
 *
 * Bulk-safe: exactly one SOQL query per trigger execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    /**
     * Runs for both contexts. For inserts every qualifying contact is checked;
     * for updates only contacts whose Email or AccountId changed are checked.
     */
    private void run(List<Contact> newList, Map<Id, Contact> oldMap) {
        // Qualifying contacts to validate, in trigger order.
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();

        for (Contact c : newList) {
            if (c.AccountId == null || c.Email == null) {
                continue;
            }
            if (oldMap != null) {
                Contact oldC = oldMap.get(c.Id);
                Boolean emailChanged = oldC.Email != c.Email
                    && (oldC.Email == null || !oldC.Email.equalsIgnoreCase(c.Email));
                Boolean accountChanged = oldC.AccountId != c.AccountId;
                if (!emailChanged && !accountChanged) {
                    continue;
                }
            }
            toCheck.add(c);
            accountIds.add(c.AccountId);
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // Single SOQL: existing contacts (other than the ones in this save)
        // on the relevant accounts that have an email.
        Set<Id> idsInTrigger = (oldMap != null)
            ? newList.keySet()
            : new Set<Id>();
        Map<String, Set<Id>> existingAccountsByEmail = new Map<String, Set<Id>>();
        for (Contact existing : [
            SELECT AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
              AND Id NOT IN :idsInTrigger
        ]) {
            String key = normalize(existing.AccountId, existing.Email);
            if (!existingAccountsByEmail.containsKey(key)) {
                existingAccountsByEmail.put(key, new Set<Id>());
            }
            existingAccountsByEmail.get(key).add(existing.Id);
        }

        // In-order walk: first contact on a given (account, email) is accepted,
        // each later one is rejected.
        Set<String> acceptedKeys = new Set<String>();
        for (Contact c : toCheck) {
            String key = normalize(c.AccountId, c.Email);
            if (acceptedKeys.contains(key)
                    || existingAccountsByEmail.containsKey(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                acceptedKeys.add(key);
            }
        }
    }

    private static String normalize(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }

    public void beforeInsert(List<SObject> triggerNew) {
        run((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        run((List<Contact>) triggerNew, (Map<Id, Contact>) triggerOld);
    }
}
