/**
 * Singleton query provider for Contact before-insert trigger actions.
 *
 * The inner Service class is registered as a Trigger Action (Order 1) so that the
 * account map is loaded exactly once per trigger execution and shared by all
 * later actions. The map is reloaded on every execution because later DML in
 * the same transaction may involve other accounts.
 */
public inherited sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    @TestVisible
    private Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Loads the parent accounts for the given contacts, replacing any
     * previously loaded records so values are always current.
     */
    @TestVisible
    private void loadAccounts(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            accountsById = new Map<Id, Account>();
            return;
        }
        accountsById = new Map<Id, Account>([
            SELECT Id, BillingStreet, BillingCity, BillingPostalCode, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);
    }

    /**
     * Trigger action that primes the singleton before any other action runs.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {

        public void beforeInsert(List<SObject> triggerNew) {
            TA_Contact_Queries.getInstance().loadAccounts((List<Contact>) triggerNew);
        }
    }
}
